import type { MetadataRoute } from "next";
import { siteConfig } from "@/app/config/seo";
import { defaultLocale } from "@/shared/i18n/locales";

/**
 * Web App Manifest: installable on Android/desktop Chromium, iOS/iPadOS
 * 16.4+ (home-screen web apps get Web Push there), macOS Safari 17+.
 * Icons and screenshots are generated by `app/icons/[file]/route.tsx`.
 * The manifest is not localized (one per origin); `start_url` is the
 * locale-less `/tasks`, which proxy.ts redirects to the visitor's language
 * (and to sign-in when there is no session).
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: siteConfig.name,
    short_name: siteConfig.name,
    description: siteConfig.description,
    lang: defaultLocale,
    dir: "auto",
    start_url: "/tasks?source=pwa",
    scope: "/",
    display: "standalone",
    display_override: ["window-controls-overlay", "standalone"],
    orientation: "any",
    background_color: siteConfig.themeColor.light,
    theme_color: siteConfig.themeColor.light,
    categories: ["productivity", "utilities"],
    prefer_related_applications: false,
    icons: [
      { src: "/favicon.ico", sizes: "any", type: "image/x-icon" },
      {
        src: "/icons/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
      {
        src: "/icons/badge-96.png",
        sizes: "96x96",
        type: "image/png",
        purpose: "monochrome",
      },
    ],
    screenshots: [
      {
        src: "/icons/screenshot-wide.png",
        sizes: "1280x720",
        type: "image/png",
        form_factor: "wide",
        label: "Tasks dashboard",
      },
      {
        src: "/icons/screenshot-narrow.png",
        sizes: "720x1280",
        type: "image/png",
        form_factor: "narrow",
        label: "Tasks on a phone",
      },
    ],
    shortcuts: [
      {
        name: "New task",
        short_name: "New",
        url: "/tasks/new?source=pwa-shortcut",
        icons: [{ src: "/icons/icon-192.png", sizes: "192x192" }],
      },
      {
        name: "Search",
        url: "/search?source=pwa-shortcut",
        icons: [{ src: "/icons/icon-192.png", sizes: "192x192" }],
      },
      {
        name: "Notifications",
        url: "/notifications?source=pwa-shortcut",
        icons: [{ src: "/icons/icon-192.png", sizes: "192x192" }],
      },
    ],
  };
}
